<body>
  <h1>Todos</h1>
  <form class="add-form" id="addForm">
    <input type="text" id="titleInput" placeholder="What needs to be done?" required aria-label="New todo title">
    <input type="date" id="dueDateInput" aria-label="Due date (optional)">
    <button type="submit">Add</button>
  </form>
  <div class="filters" id="filters">
    <button class="filter-btn" id="filterOverdue" type="button">Show Overdue</button>
    <button class="filter-btn" id="clearCompleted" type="button">Clear completed</button>
  </div>
  <ul class="todo-list" id="todoList" role="list" aria-label="Todo items"></ul>

  <script>
    const API = '/api/todos';
    const todoList = document.getElementById('todoList');
    const addForm = document.getElementById('addForm');
    const titleInput = document.getElementById('titleInput');
    const dueDateInput = document.getElementById('dueDateInput');
    const filterOverdueBtn = document.getElementById('filterOverdue');
    const clearCompletedBtn = document.getElementById('clearCompleted');
    let showOverdueOnly = false;
    let editingTodoId = null;

    async function loadTodos() {
      const url = showOverdueOnly ? `${API}?overdue=true` : API;
      const res = await fetch(url);
      const todos = await res.json();
      renderTodos(todos);
    }

    function formatDate(dateStr) {
      if (!dateStr) return '';
      const d = new Date(dateStr + 'T00:00:00');
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    }

    function isOverdue(todo) {
      if (!todo.due_date || todo.completed) return false;
      const today = new Date().toISOString().split('T')[0];
      return todo.due_date < today;
    }

    function renderTodos(todos) {
      if (todos.length === 0) {
        todoList.innerHTML = '<li class="empty">No todos yet. Add one above!</li>';
        return;
      }
      todoList.innerHTML = todos.map(todo => {
        const isEditing = editingTodoId === todo.id;
        if (isEditing) {
          return `
            <li class="todo-item editing" data-id="${todo.id}">
              <form class="edit-form" data-id="${todo.id}">
                <div class="edit-fields">
                  <input type="text" class="edit-title" value="${escapeHtml(todo.title)}" required aria-label="Edit title for ${escapeHtml(todo.title)}">
                  <input type="date" class="edit-due-date" value="${todo.due_date || ''}" aria-label="Edit due date for ${escapeHtml(todo.title)}">
                </div>
                <div class="todo-actions">
                  <button type="submit" class="save-btn">Save</button>
                  <button type="button" class="cancel-edit-btn">Cancel</button>
                </div>
              </form>
            </li>
          `;
        }

        return `
          <li class="todo-item ${todo.completed ? 'completed' : ''} ${isOverdue(todo) ? 'overdue' : ''}" data-id="${todo.id}">
            <input type="checkbox" ${todo.completed ? 'checked' : ''} aria-label="Mark ${escapeHtml(todo.title)} as ${todo.completed ? 'incomplete' : 'complete'}">
            <div class="todo-main">
              <label>${escapeHtml(todo.title)}</label>
              ${todo.due_date ? `<span class="due-date ${isOverdue(todo) ? 'overdue' : ''}">${formatDate(todo.due_date)}</span>` : ''}
            </div>
            <div class="todo-actions">
              <button class="edit-btn" type="button" aria-label="Edit ${escapeHtml(todo.title)}">Edit</button>
              <button class="delete-btn" type="button" aria-label="Delete ${escapeHtml(todo.title)}">&times;</button>
            </div>
          </li>
        `;
      }).join('');
    }

    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    addForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const title = titleInput.value.trim();
      if (!title) return;
      const due_date = dueDateInput.value || null;
      await fetch(API, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, due_date })
      });
      titleInput.value = '';
      dueDateInput.value = '';
      loadTodos();
    });

    filterOverdueBtn.addEventListener('click', () => {
      showOverdueOnly = !showOverdueOnly;
      filterOverdueBtn.classList.toggle('active', showOverdueOnly);
      filterOverdueBtn.textContent = showOverdueOnly ? 'Show All' : 'Show Overdue';
      loadTodos();
    });

    clearCompletedBtn.addEventListener('click', async () => {
      await fetch(`${API}/completed`, { method: 'DELETE' });
      editingTodoId = null;
      loadTodos();
    });

    todoList.addEventListener('change', async (e) => {
      if (e.target.type === 'checkbox') {
        const id = e.target.closest('.todo-item').dataset.id;
        await fetch(`${API}/${id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: e.target.checked })
        });
        loadTodos();
      }
    });

    todoList.addEventListener('submit', async (e) => {
      if (e.target.classList.contains('edit-form')) {
        e.preventDefault();
        const form = e.target;
        const id = form.dataset.id;
        const title = form.querySelector('.edit-title').value.trim();
        const due_date = form.querySelector('.edit-due-date').value || null;
        if (!title) return;
        await fetch(`${API}/${id}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title, due_date })
        });
        editingTodoId = null;
        loadTodos();
      }
    });

    todoList.addEventListener('click', async (e) => {
      if (e.target.classList.contains('edit-btn')) {
        editingTodoId = Number(e.target.closest('.todo-item').dataset.id);
        loadTodos();
        return;
      }
      if (e.target.classList.contains('cancel-edit-btn')) {
        editingTodoId = null;
        loadTodos();
        return;
      }
      if (e.target.classList.contains('delete-btn')) {
        const id = e.target.closest('.todo-item').dataset.id;
        await fetch(`${API}/${id}`, { method: 'DELETE' });
        editingTodoId = null;
        loadTodos();
      }
    });

    loadTodos();
  </script>
</body>
</html>
